// 小工具

static Matrix table_matrix(const double* t, int N) {
    Matrix a(N, N);
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) a(i, j) = cplx{t[2 * (i * N + j)], t[2 * (i * N + j) + 1]};
    return a;
}

// max|a − b| / max|b|；形状不同或出现 NaN 时返回 NaN。b 全为零时按 1 归一。
static double rel_diff(const Matrix& a, const Matrix& b) {
    if (a.rows() != b.rows() || a.cols() != b.cols()) return std::numeric_limits<double>::quiet_NaN();
    double scale = max_abs(b);
    if (!(scale > 0.0)) scale = 1.0;
    double worst = 0.0;
    for (int j = 0; j < b.cols(); ++j)
        for (int i = 0; i < b.rows(); ++i) {
            const double d = std::abs(a(i, j) - b(i, j));
            if (std::isnan(d)) return d;
            worst = (std::max)(worst, d);
        }
    return worst / scale;
}

static bool same_bits(const Matrix& a, const Matrix& b) {
    return a.rows() == b.rows() && a.cols() == b.cols() &&
           std::memcmp(a.data(), b.data(), sizeof(cplx) * static_cast<std::size_t>(a.rows()) * a.cols()) == 0;
}
static bool same_bits(const d2::LayerOperators2D& a, const d2::LayerOperators2D& b) {
    return same_bits(a.eps, b.eps) && same_bits(a.cx, b.cx) && same_bits(a.cy, b.cy);
}

static XProfile2D uniform_profile(double L, cplx n) { return XProfile2D{{0.0, L}, {n}}; }

// 取出名为 name 的算例。
static const OpsCase& find_case(const std::vector<OpsCase>& cases, const char* name) {
    for (const OpsCase& c : cases)
        if (std::strcmp(c.name, name) == 0) return c;
    throw std::logic_error("找不到算例");
}

static d2::LayerOperators2D ops_of(const OpsCase& c, int M1, int M2, bool parallel = false) {
    return d2::layer_operators(c.layer, c.Lx, c.Ly, M1, M2, c.fact, parallel);
}

// 与 d2::eps_at 独立的另一种写法：把 x 平移到 [x_0, x_0 + Lx)，再逐段线性查找（折射率，不是 ε）。
static cplx index_at(const XProfile2D& p, double x, double Lx) {
    double xx = x;
    while (xx < p.edges.front()) xx += Lx;
    while (xx >= p.edges.front() + Lx) xx -= Lx;
    for (std::size_t k = 0; k < p.n_values.size(); ++k)
        if (xx < p.edges[k + 1]) return p.n_values[k];
    return p.n_values.back();
}

// 转置结构：ε′(x′, y′) = ε(x = y′, y = x′)，周期 Lx′ = Ly、Ly′ = Lx。
// 新的 y′ 分段是原来的 x 切点集合，每个分段内沿 x′（即原来的 y）的剖面取原来各 y 分段的折射率在该 x 小段中点的值。
static Layer2D transpose_layer(const Layer2D& L, double Lx) {
    const std::vector<double> cuts = d2::merge_x_cuts(L.x_profiles, Lx);
    std::vector<XProfile2D> rows;
    for (std::size_t j = 0; j + 1 < cuts.size(); ++j) {
        const double xm = 0.5 * (cuts[j] + cuts[j + 1]);
        XProfile2D p;
        p.edges = L.y_edges;
        for (const XProfile2D& q : L.x_profiles) p.n_values.push_back(index_at(q, xm, Lx));
        rows.push_back(std::move(p));
    }
    return Layer2D::patterned(L.d, cuts, std::move(rows), L.name + "（转置）");
}

// a 是原结构（截断 M1、M2）的算子，b 是转置结构（截断 M2、M1）的算子：谐波 (m, n) 对应 (n, m)。返回 max|a_ij − b_σ(i)σ(j)| / max|a|。
static double transposed_diff(const Matrix& a, const Matrix& b, int M1, int M2) {
    double worst = 0.0;
    for (int m = -M1; m <= M1; ++m)
        for (int n = -M2; n <= M2; ++n)
            for (int mp = -M1; mp <= M1; ++mp)
                for (int np = -M2; np <= M2; ++np) {
                    const int i = rcwa::harmonic_index_2d(m, n, M1, M2), j = rcwa::harmonic_index_2d(mp, np, M1, M2);
                    const int ti = rcwa::harmonic_index_2d(n, m, M2, M1), tj = rcwa::harmonic_index_2d(np, mp, M2, M1);
                    const double d = std::abs(a(i, j) - b(ti, tj));
                    if (std::isnan(d)) return d;
                    worst = (std::max)(worst, d);
                }
    const double scale = max_abs(a);
    return worst / (scale > 0.0 ? scale : 1.0);
}

// 块 Toeplitz 偏差：(m,n),(m′,n′) 元只应依赖 (m − m′, n − n′)。每个差值取第一个出现的元素作参照，返回最大偏差 / max|A|。
static double toeplitz_defect(const Matrix& A, int M1, int M2) {
    const int n2 = 2 * M2 + 1, nd2 = 4 * M2 + 1;
    std::vector<cplx> ref(static_cast<std::size_t>((4 * M1 + 1) * nd2));
    std::vector<char> seen(ref.size(), 0);
    double worst = 0.0;
    for (int col = 0; col < A.cols(); ++col)
        for (int row = 0; row < A.rows(); ++row) {
            const int m = row / n2 - M1, n = row % n2 - M2, mp = col / n2 - M1, np = col % n2 - M2;
            const std::size_t key = static_cast<std::size_t>((m - mp + 2 * M1) * nd2 + (n - np + 2 * M2));
            if (!seen[key]) {
                seen[key] = 1;
                ref[key] = A(row, col);
            } else {
                worst = (std::max)(worst, std::abs(A(row, col) - ref[key]));
            }
        }
    const double scale = max_abs(A);
    return worst / (scale > 0.0 ? scale : 1.0);
}

// 哪个元素的 harmonic (m, n) 与 (m′, n′) 的第二指标不同（n ≠ n′）的最大模 / max|A|：y 不变的层里这些应当是舍入误差。
static double off_diagonal_in_n(const Matrix& A, int M2) {
    const int n2 = 2 * M2 + 1;
    double worst = 0.0;
    for (int col = 0; col < A.cols(); ++col)
        for (int row = 0; row < A.rows(); ++row)
            if (row % n2 != col % n2) worst = (std::max)(worst, std::abs(A(row, col)));
    const double scale = max_abs(A);
    return worst / (scale > 0.0 ? scale : 1.0);
}
// 同理，m ≠ m′ 的元素（x 不变的层）。
static double off_diagonal_in_m(const Matrix& A, int M2) {
    const int n2 = 2 * M2 + 1;
    double worst = 0.0;
    for (int col = 0; col < A.cols(); ++col)
        for (int row = 0; row < A.rows(); ++row)
            if (row / n2 != col / n2) worst = (std::max)(worst, std::abs(A(row, col)));
    const double scale = max_abs(A);
    return worst / (scale > 0.0 ? scale : 1.0);
}

// 把 A 里 n = n′ 的块（行 (m, n)、列 (m′, n)）取成 (2M1+1) 阶方阵。
static Matrix block_of_n(const Matrix& A, int M1, int M2, int n) {
    const int n2 = 2 * M2 + 1, n1 = 2 * M1 + 1;
    Matrix b(n1, n1);
    for (int j = 0; j < n1; ++j)
        for (int i = 0; i < n1; ++i) b(i, j) = A(i * n2 + (n + M2), j * n2 + (n + M2));
    return b;
}
// 把 A 里 m = m′ 的块（行 (m, n)、列 (m, n′)）取成 (2M2+1) 阶方阵。
static Matrix block_of_m(const Matrix& A, int M1, int M2, int m) {
    const int n2 = 2 * M2 + 1;
    Matrix b(n2, n2);
    for (int j = 0; j < n2; ++j)
        for (int i = 0; i < n2; ++i) b(i, j) = A((m + M1) * n2 + i, (m + M1) * n2 + j);
    return b;
}

// ---------------------------------------------------------------------------------------------
// 1. 一维 Fourier 工具

static void test_fourier_toeplitz_seg() {
    say("[fourier_1d、toeplitz_1d、seg_fourier]\n");
    // Python 参照
    {
        const std::vector<double> e1{-0.3, 0.1, 0.45, 0.7};
        const Vector v1{1.0, 2.89, cplx{0.96, 0.4}};
        const Vector c1 = d2::fourier_1d(e1, v1, 1.0, 5);
        CHECK(c1.size() == 11);
        double w1 = 0.0;
        for (std::size_t h = 0; h < c1.size() && h < 11; ++h)
            w1 = (std::max)(w1, std::abs(c1[h] - cplx{k_fourier1[2 * h], k_fourier1[2 * h + 1]}));
        const std::vector<double> e2{0.2, 0.5, 1.0};
        const Vector v2{cplx{1.5, -0.1}, 3.0};
        const Vector c2 = d2::fourier_1d(e2, v2, 0.8, 3);
        CHECK(c2.size() == 7);
        double w2 = 0.0;
        for (std::size_t h = 0; h < c2.size() && h < 7; ++h)
            w2 = (std::max)(w2, std::abs(c2[h] - cplx{k_fourier2[2 * h], k_fourier2[2 * h + 1]}));
        say("  fourier_1d 与 Python 最大差：%.2e（起点 −0.3 的 3 段）、%.2e（起点 0.2、周期 0.8 的 2 段）\n", w1, w2);
        CHECK_LE(w1, 1e-13);
        CHECK_LE(w2, 1e-13);
    }
    // 方波的闭式解：f = a（0 ≤ x < d）、b（d ≤ x < P）。c_0 = (a·d + b·(P−d))/P，c_h = (a − b)(1 − e^{−2πihd/P})/(2πih)
    {
        const cplx a{1.5, 0.2}, b{2.7, -0.1};
        const double P = 0.7, d = 0.25;
        const Vector c = d2::fourier_1d({0.0, d, P}, {a, b}, P, 8);
        double worst = std::abs(c[8] - (a * d + b * (P - d)) / P);
        for (int h = -8; h <= 8; ++h) {
            if (h == 0) continue;
            const cplx expect = (a - b) * (1.0 - std::exp(cplx{0.0, -2.0 * kPi * h * d / P})) / cplx{0.0, 2.0 * kPi * h};
            worst = (std::max)(worst, std::abs(c[static_cast<std::size_t>(h + 8)] - expect));
        }
        say("  方波闭式解最大差：%.2e\n", worst);
        CHECK_LE(worst, 1e-14);
    }
    // 单个分段：c_0 = n²，其余只剩舍入误差（不清零，见头文件说明）
    {
        const cplx e = cplx{1.4, 0.3} * cplx{1.4, 0.3};
        const Vector c = d2::fourier_1d({0.0, 1.0}, {e}, 1.0, 6);
        double rest = 0.0;
        for (int h = -6; h <= 6; ++h)
            if (h != 0) rest = (std::max)(rest, std::abs(c[static_cast<std::size_t>(h + 6)]));
        CHECK_LE(std::abs(c[6] - e), 1e-15);
        CHECK_LE(rest, 1e-14);
        CHECK(d2::fourier_1d({0.0, 1.0}, {e}, 1.0, 0).size() == 1);
    }
    CHECK_THROWS(d2::fourier_1d({0.0, 1.0}, {1.0, 2.0}, 1.0, 2), std::invalid_argument);
    CHECK_THROWS(d2::fourier_1d({0.0, 1.0}, {1.0}, 1.0, -1), std::invalid_argument);

    // toeplitz_1d：(i, j) 元 = c[i − j + 2M]
    {
        Vector c(9);
        for (int k = 0; k < 9; ++k) c[static_cast<std::size_t>(k)] = cplx{k + 1.0, 0.5 * (k - 3)};
        const Matrix T = d2::toeplitz_1d(c, 2);
        CHECK(T.rows() == 5 && T.cols() == 5);
        CHECK(rel_diff(T, table_matrix(k_toeplitz, 5)) == 0.0);
        for (int i = 0; i < 5; ++i)
            for (int j = 0; j < 5; ++j) CHECK(T(i, j) == c[static_cast<std::size_t>(i - j + 4)]);
        CHECK(d2::toeplitz_1d(Vector{cplx{3.0, 1.0}}, 0)(0, 0) == cplx(3.0, 1.0));
        CHECK_THROWS(d2::toeplitz_1d(c, 3), std::invalid_argument);
        CHECK_THROWS(d2::toeplitz_1d(c, -1), std::invalid_argument);
    }

    // seg_fourier
    {
        const Matrix w1 = d2::seg_fourier({-0.2, 0.1, 0.5, 0.8}, 4, 1.0);
        CHECK(w1.rows() == 3 && w1.cols() == 9);
        double e1 = 0.0;
        for (int k = 0; k < 3 && w1.rows() == 3; ++k)
            for (int h = 0; h < 9 && w1.cols() == 9; ++h)
                e1 = (std::max)(e1, std::abs(w1(k, h) - cplx{k_seg1[2 * (k * 9 + h)], k_seg1[2 * (k * 9 + h) + 1]}));
        const Matrix w2 = d2::seg_fourier({0.0, 0.3, 0.45, 0.9}, 0, 0.9);
        CHECK(w2.rows() == 3 && w2.cols() == 1);
        double e2 = 0.0;
        for (int k = 0; k < 3 && w2.rows() == 3; ++k) e2 = (std::max)(e2, std::abs(w2(k, 0) - cplx{k_seg2[2 * k], k_seg2[2 * k + 1]}));
        say("  seg_fourier 与 Python 最大差：%.2e（hmax = 4）、%.2e（hmax = 0）\n", e1, e2);
        CHECK_LE(e1, 1e-14);
        CHECK_LE(e2, 1e-15);
        // 各分段的贡献加起来是整个周期的积分：h = 0 为 1，h ≠ 0 为 0
        double sum_err = 0.0;
        for (int h = 0; h < 9; ++h) {
            cplx s{};
            for (int k = 0; k < 3; ++k) s += w1(k, h);
            sum_err = (std::max)(sum_err, std::abs(s - (h == 4 ? 1.0 : 0.0)));
        }
        CHECK_LE(sum_err, 1e-15);
        CHECK_THROWS(d2::seg_fourier({0.0}, 2, 1.0), std::invalid_argument);
    }
}

// ---------------------------------------------------------------------------------------------
// 2. eps_at：x 剖面的周期回绕

static void test_eps_at() {
    say("[eps_at：x 剖面的周期回绕]\n");
    const XProfile2D PA{{-0.3, 0.1, 0.45, 0.7}, {1.0, 1.7, cplx{1.0, 0.2}}};
    const XProfile2D PB{{0.45, 0.8, 1.2, 1.45}, {1.3, 1.0, 1.9}};
    const XProfile2D PC{{1.2, 1.5, 1.9, 2.2}, {2.0, 1.0, 1.4}};
    const XProfile2D PD{{0.0, 0.3, 1.0}, {1.5, 1.0}};
    const XProfile2D* profiles[4] = {&PA, &PB, &PC, &PD};
    const int nx = static_cast<int>(sizeof k_eps_at_x / sizeof k_eps_at_x[0]);
    double worst = 0.0;
    for (int p = 0; p < 4; ++p)
        for (int ix = 0; ix < nx; ++ix) {
            const cplx got = d2::eps_at(*profiles[p], k_eps_at_x[ix], 1.0);
            const double* t = &k_eps_at[2 * (p * nx + ix)];
            worst = (std::max)(worst, std::abs(got - cplx{t[0], t[1]}));
        }
    say("  周期 1：%d 个剖面 × %d 个 x，与 Python 最大差 %.2e\n", 4, nx, worst);
    CHECK_LE(worst, 1e-15);

    const XProfile2D PE{{0.3, 0.6, 1.2}, {1.2, 2.0}};
    const int nx2 = static_cast<int>(sizeof k_eps_at_x2 / sizeof k_eps_at_x2[0]);
    double worst2 = 0.0;
    for (int ix = 0; ix < nx2; ++ix) {
        const cplx got = d2::eps_at(PE, k_eps_at_x2[ix], 0.9);
        worst2 = (std::max)(worst2, std::abs(got - cplx{k_eps_at2[2 * ix], k_eps_at2[2 * ix + 1]}));
    }
    say("  周期 0.9：%d 个 x，与 Python 最大差 %.2e\n", nx2, worst2);
    CHECK_LE(worst2, 1e-15);

    // 与另一种写法（平移 + 线性查找）在 x 的随机点上比较（避开边界）
    std::uint32_t s = 20260101u;
    int disagree = 0;
    for (int t = 0; t < 4000; ++t) {
        s = s * 1664525u + 1013904223u;
        const double x = (static_cast<double>(s >> 8) / 16777216.0) * 14.0 - 7.0;
        for (const XProfile2D* p : profiles) {
            const cplx n = index_at(*p, x, 1.0);
            if (std::abs(d2::eps_at(*p, x, 1.0) - n * n) > 1e-15) ++disagree;
        }
    }
    CHECK(disagree == 0);

    // 手算几例：PA 在 x = 0.8（回绕后落在 −0.2，第 0 段）、x = 0.9（回绕后 −0.1，第 0 段）、x = 0.2（第 1 段）
    CHECK(std::abs(d2::eps_at(PA, 0.8, 1.0) - 1.0) <= 1e-15);
    CHECK(std::abs(d2::eps_at(PA, 0.2, 1.0) - 1.7 * 1.7) <= 1e-15);
    CHECK(std::abs(d2::eps_at(PA, 0.5, 1.0) - cplx{1.0, 0.2} * cplx{1.0, 0.2}) <= 1e-15);
    // x 比起点小一个 ulp：回绕后 xx 舍入到 xe.back()，searchsorted 越过末边界，要夹回最后一段（Python 的 np.clip）
    CHECK(std::abs(d2::eps_at(PA, -0.30000000000000004, 1.0) - cplx{1.0, 0.2} * cplx{1.0, 0.2}) <= 1e-15);
    CHECK(std::abs(d2::eps_at(PD, -5e-324, 1.0) - 1.0) <= 1e-15);
    CHECK_THROWS(d2::eps_at(XProfile2D{}, 0.5, 1.0), std::invalid_argument);
}

// ---------------------------------------------------------------------------------------------
// 3. x 切点集合的合并去重

static void test_merge_x_cuts() {
    say("[merge_x_cuts：取模 Lx、round 到 12 位、筛 [−1e-12, Lx+1e-12]、补 0 与 Lx]\n");
    int exact = 0, total = 0;
    for (const auto& c : k_cut_cases) {
        std::vector<XProfile2D> profiles;
        for (const std::vector<double>& e : *c.in) {
            XProfile2D p;
            p.edges = e;
            p.n_values.assign(e.size() - 1, cplx{1.0, 0.0});
            profiles.push_back(std::move(p));
        }
        const std::vector<double> got = d2::merge_x_cuts(profiles, c.Lx);
        const bool ok = got == *c.out;   // 与 Python 的 np.unique / np.round 逐位相同
        ++total;
        exact += ok;
        CHECK(ok);
        if (!ok) {
            say("    %s：期望 %zu 个切点：", c.name, c.out->size());
            for (double v : *c.out) say(" %.17g", v);
            say("；得到 %zu 个：", got.size());
            for (double v : got) say(" %.17g", v);
            say("\n");
        }
    }
    say("  %d / %d 组切点与 Python 逐位相同\n", exact, total);
    // 手算：起点 −0.3 的剖面 [−0.3, 0.1, 0.45, 0.7]（周期 1）取模后 0.7、0.1、0.45、0.7，加上 0、1
    {
        std::vector<XProfile2D> profiles{XProfile2D{{-0.3, 0.1, 0.45, 0.7}, {1.0, 2.0, 3.0}}};
        const std::vector<double> expect{0.0, 0.1, 0.45, 0.7, 1.0};
        const std::vector<double> got = d2::merge_x_cuts(profiles, 1.0);
        CHECK(got.size() == expect.size());
        double worst = 0.0;
        for (std::size_t k = 0; k < got.size() && k < expect.size(); ++k) worst = (std::max)(worst, std::abs(got[k] - expect[k]));
        CHECK_LE(worst, 1e-15);
        // 0.1 + 0.2 与 0.3 在 12 位舍入后是同一个切点
        profiles = {XProfile2D{{0.0, 0.1 + 0.2, 1.0}, {1.0, 2.0}}, XProfile2D{{0.0, 0.3, 1.0}, {1.0, 2.0}}};
        CHECK(d2::merge_x_cuts(profiles, 1.0) == (std::vector<double>{0.0, 0.3, 1.0}));
        CHECK(d2::floor_mod(-0.25, 1.0) == 0.75);
        CHECK(d2::floor_mod(2.0, 1.0) == 0.0 && !std::signbit(d2::floor_mod(2.0, 1.0)));
    }
}

// ---------------------------------------------------------------------------------------------
// 4. 装配

static void test_assemble() {
    say("[assemble_xfirst、assemble_yfirst]\n");
    // Python 参照：M1 = 1、M2 = 2，块元素 = h·10000 + i·100 + j
    {
        const int M1 = 1, M2 = 2, N = 15;
        std::vector<Matrix> bx(4 * M2 + 1, Matrix(2 * M1 + 1, 2 * M1 + 1));
        for (int h = 0; h < 4 * M2 + 1; ++h)
            for (int i = 0; i < 2 * M1 + 1; ++i)
                for (int j = 0; j < 2 * M1 + 1; ++j) bx[static_cast<std::size_t>(h)](i, j) = h * 10000 + i * 100 + j;
        std::vector<Matrix> by(4 * M1 + 1, Matrix(2 * M2 + 1, 2 * M2 + 1));
        for (int h = 0; h < 4 * M1 + 1; ++h)
            for (int i = 0; i < 2 * M2 + 1; ++i)
                for (int j = 0; j < 2 * M2 + 1; ++j) by[static_cast<std::size_t>(h)](i, j) = h * 10000 + i * 100 + j;
        const Matrix Ax = d2::assemble_xfirst(bx, M1, M2), Ay = d2::assemble_yfirst(by, M1, M2);
        CHECK(Ax.rows() == N && Ax.cols() == N && Ay.rows() == N && Ay.cols() == N);
        int bad_x = 0, bad_y = 0;
        for (int i = 0; i < N && Ax.rows() == N; ++i)
            for (int j = 0; j < N && Ax.cols() == N; ++j) {
                if (Ax(i, j) != cplx{static_cast<double>(k_assemble_x[i * N + j]), 0.0}) ++bad_x;
                if (Ay(i, j) != cplx{static_cast<double>(k_assemble_y[i * N + j]), 0.0}) ++bad_y;
            }
        say("  M1 = 1、M2 = 2：与 Python 的 _assemble_xfirst / _assemble_yfirst 不同的元素个数 %d / %d\n", bad_x, bad_y);
        CHECK(bad_x == 0);
        CHECK(bad_y == 0);
        // parallel = true 与串行逐位相同
        CHECK(same_bits(d2::assemble_xfirst(bx, M1, M2, true), Ax));
        CHECK(same_bits(d2::assemble_yfirst(by, M1, M2, true), Ay));
    }
    // 其它截断（含 0）：直接按定义逐元素核对（四重循环，与实现的列循环写法不同）
    const int combos[][2] = {{0, 0}, {0, 3}, {3, 0}, {2, 2}, {4, 1}};
    for (const auto& mc : combos) {
        const int M1 = mc[0], M2 = mc[1], n1 = 2 * M1 + 1, n2 = 2 * M2 + 1, N = n1 * n2;
        std::vector<Matrix> bx(static_cast<std::size_t>(4 * M2 + 1), Matrix(n1, n1)), by(static_cast<std::size_t>(4 * M1 + 1), Matrix(n2, n2));
        for (int h = 0; h < 4 * M2 + 1; ++h)
            for (int i = 0; i < n1; ++i)
                for (int j = 0; j < n1; ++j) bx[static_cast<std::size_t>(h)](i, j) = cplx{h * 10000.0 + i * 100 + j, h - i + 0.5 * j};
        for (int h = 0; h < 4 * M1 + 1; ++h)
            for (int i = 0; i < n2; ++i)
                for (int j = 0; j < n2; ++j) by[static_cast<std::size_t>(h)](i, j) = cplx{h * 10000.0 + i * 100 + j, i - h + 0.25 * j};
        const Matrix Ax = d2::assemble_xfirst(bx, M1, M2), Ay = d2::assemble_yfirst(by, M1, M2);
        int bad = 0;
        for (int m = -M1; m <= M1; ++m)
            for (int n = -M2; n <= M2; ++n)
                for (int mp = -M1; mp <= M1; ++mp)
                    for (int np = -M2; np <= M2; ++np) {
                        const int i = rcwa::harmonic_index_2d(m, n, M1, M2), j = rcwa::harmonic_index_2d(mp, np, M1, M2);
                        if (Ax(i, j) != bx[static_cast<std::size_t>(n - np + 2 * M2)](m + M1, mp + M1)) ++bad;
                        if (Ay(i, j) != by[static_cast<std::size_t>(m - mp + 2 * M1)](n + M2, np + M2)) ++bad;
                    }
        CHECK(Ax.rows() == N && Ay.rows() == N);
        CHECK(bad == 0);
    }
    // 块个数或阶数不对
    CHECK_THROWS(d2::assemble_xfirst(std::vector<Matrix>(4, Matrix(3, 3)), 1, 1), std::invalid_argument);
    CHECK_THROWS(d2::assemble_yfirst(std::vector<Matrix>(5, Matrix(2, 2)), 1, 1), std::invalid_argument);
    CHECK_THROWS(d2::assemble_xfirst(std::vector<Matrix>(5, Matrix(3, 3)), -1, 1), std::invalid_argument);
}

// ---------------------------------------------------------------------------------------------
// 5. 均匀层

static void test_uniform() {
    say("[均匀层与退化的结构层]\n");
    const cplx n{1.5, 0.1};
    const cplx e = n * n;
    const int combos[][2] = {{0, 0}, {1, 1}, {2, 0}, {0, 3}, {3, 2}};
    double worst = 0.0;
    for (const auto& mc : combos) {
        const int N = (2 * mc[0] + 1) * (2 * mc[1] + 1);
        const d2::LayerOperators2D op = d2::layer_operators(Layer2D::uniform(0.2, n, "均匀"), 0.7, 1.9, mc[0], mc[1], Factorization2D::Li);
        bool ok = op.eps.rows() == N && op.cx.rows() == N && op.cy.rows() == N && op.eps.cols() == N;
        for (int j = 0; j < N && ok; ++j)
            for (int i = 0; i < N; ++i) {
                const cplx want = i == j ? e : cplx{};
                ok = ok && op.eps(i, j) == want && op.cx(i, j) == want && op.cy(i, j) == want;
            }
        CHECK(ok);
        // Laurent 因式分解对均匀层给出同样的结果
        const d2::LayerOperators2D lo = d2::layer_operators(Layer2D::uniform(0.2, n), 0.7, 1.9, mc[0], mc[1], Factorization2D::Laurent);
        CHECK(same_bits(lo, op));
        worst = (std::max)(worst, rel_diff(op.eps, op.cx));
    }
    // 结构层写法的均匀介质（一个 y 分段、一个 x 分段，或几段取值相同）：n²·I，非对角元只剩 1e-16 量级的舍入误差
    const Layer2D one = Layer2D::patterned(0.2, {0.0, 1.9}, {uniform_profile(0.7, n)}, "单段");
    const Layer2D split = Layer2D::patterned(0.2, {-0.5, 0.4, 1.4}, {XProfile2D{{0.1, 0.3, 0.8}, {n, n}}, uniform_profile(0.7, n)}, "分段同值");
    for (const Layer2D* L : {&one, &split}) {
        const d2::LayerOperators2D op = d2::layer_operators(*L, 0.7, 1.9, 2, 3, Factorization2D::Li);
        Matrix want(35, 35);
        for (int i = 0; i < 35; ++i) want(i, i) = e;
        const double d1 = rel_diff(op.eps, want), d2_ = rel_diff(op.cx, want), d3 = rel_diff(op.cy, want);
        say("  %s：Eps、Cx、Cy 与 n²·I 的相对差 %.1e、%.1e、%.1e\n", L->name.c_str(), d1, d2_, d3);
        CHECK_LE(d1, 1e-14);
        CHECK_LE(d2_, 1e-14);
        CHECK_LE(d3, 1e-14);
    }
    CHECK_LE(worst, 0.0);
}

// ---------------------------------------------------------------------------------------------
// 6. 对 Python 的逐元素比较

static double sample_diff(const Matrix& A, const SampleRef* s, int n) {
    double worst = 0.0;
    for (int k = 0; k < n; ++k) worst = (std::max)(worst, std::abs(A(s[k].i, s[k].j) - cplx{s[k].re, s[k].im}));
    return worst;
}

// 加权和 Σ a_ij·w_ij，w_ij = cos(0.37 i + 1.1 j) + i sin(0.53 i − 0.71 j)
static cplx weighted_sum(const Matrix& A) {
    cplx s{};
    for (int j = 0; j < A.cols(); ++j)
        for (int i = 0; i < A.rows(); ++i) s += A(i, j) * cplx{std::cos(0.37 * i + 1.1 * j), std::sin(0.53 * i - 0.71 * j)};
    return s;
}

static void test_reference_cases() {
    say("[Eps、Cx、Cy 与 Python 逐元素比较（容差 1e-12·max|b|）]\n");
    const std::vector<OpsCase> cases = build_cases();
    double worst_all = 0.0;
    for (const OpsCase& c : cases) {
        const int N = (2 * c.M1 + 1) * (2 * c.M2 + 1);
        const d2::LayerOperators2D op = ops_of(c, c.M1, c.M2);
        CHECK(op.eps.rows() == N && op.cx.rows() == N && op.cy.rows() == N);
        if (c.eps) {
            const double de = rel_diff(op.eps, table_matrix(c.eps, N));
            const double dx = rel_diff(op.cx, table_matrix(c.cx, N));
            const double dy = rel_diff(op.cy, table_matrix(c.cy, N));
            say("  %-18s N = %2d  相对最大差  Eps %.2e  Cx %.2e  Cy %.2e\n", c.name, N, de, dx, dy);
            CHECK_LE(de, 1e-12);
            CHECK_LE(dx, 1e-12);
            CHECK_LE(dy, 1e-12);
            worst_all = (std::max)(worst_all, (std::max)(de, (std::max)(dx, dy)));
        } else {
            // 采样算例：采样元素、Frobenius 范数、最大模、加权和
            const Matrix* mats[3] = {&op.eps, &op.cx, &op.cy};
            const SampleRef* samples[3] = {c.s_eps, c.s_cx, c.s_cy};
            const char* names[3] = {"Eps", "Cx", "Cy"};
            for (int q = 0; q < 3; ++q) {
                const MatrixSummary& sum = c.sums[q];
                const double ds = sample_diff(*mats[q], samples[q], c.n_samples) / sum.max;
                const double dfro = std::abs(norm_fro(*mats[q]) - sum.fro) / sum.fro;
                const double dmax = std::abs(max_abs(*mats[q]) - sum.max) / sum.max;
                const double dws = std::abs(weighted_sum(*mats[q]) - cplx{sum.wre, sum.wim}) / (sum.max * N);
                say("  %-18s N = %2d  %-3s 采样元素 %.2e  Frobenius %.2e  最大模 %.2e  加权和 %.2e（%d 个采样元素）\n", c.name, N, names[q], ds, dfro, dmax,
                    dws, c.n_samples);
                CHECK_LE(ds, 1e-12);
                CHECK_LE(dfro, 1e-12);
                CHECK_LE(dmax, 1e-12);
                CHECK_LE(dws, 1e-12);
                worst_all = (std::max)(worst_all, (std::max)((std::max)(ds, dfro), (std::max)(dmax, dws)));
            }
        }
        // 串行与 parallel = true（线程数默认 1）逐位相同
        CHECK(same_bits(ops_of(c, c.M1, c.M2, true), op));
        // 不同的 M 取同一结构：Eps 的左上角子块不变（⟦ε⟧ 的元素只取决于谐波差），验证 M 的作用只是截断
        if (c.fact == Factorization2D::Li && c.M1 >= 1 && c.M2 >= 1 && N <= 25) {
            const d2::LayerOperators2D small = ops_of(c, c.M1 - 1, c.M2 - 1);
            double worst = 0.0;
            const int s1 = 2 * (c.M1 - 1) + 1, s2 = 2 * (c.M2 - 1) + 1, n2 = 2 * c.M2 + 1;
            for (int m = 0; m < s1; ++m)
                for (int n = 0; n < s2; ++n)
                    for (int mp = 0; mp < s1; ++mp)
                        for (int np = 0; np < s2; ++np)
                            worst = (std::max)(worst, std::abs(small.eps(m * s2 + n, mp * s2 + np) - op.eps((m + 1) * n2 + (n + 1), (mp + 1) * n2 + (np + 1))));
            CHECK_LE(worst / max_abs(op.eps), 1e-14);
        }
    }
    say("  全部算例中的最大相对差：%.2e\n", worst_all);
    CHECK_LE(worst_all, 1e-12);
}

// ---------------------------------------------------------------------------------------------
// 7. 闭式解（M1 = M2 = 0）

static void test_closed_form() {
    say("[M1 = M2 = 0 的闭式解（不依赖 Python）]\n");
    // 矩形柱：y 分段 [0, y0] 背景 | [y0, y1] 含柱 | [y1, Ly] 背景；中间段 x 剖面 [0, x0] 背景 | [x0, x1] 柱 | [x1, Lx] 背景
    const double Lx = 0.9, Ly = 1.3, x0 = 0.25, x1 = 0.7, y0 = 0.4, y1 = 1.0;
    const cplx nb{1.45, 0.02}, np{1.8, 0.13};
    const Layer2D L = Layer2D::patterned(0.3, {0.0, y0, y1, Ly},
                                         {uniform_profile(Lx, nb), XProfile2D{{0.0, x0, x1, Lx}, {nb, np, nb}}, uniform_profile(Lx, nb)}, "矩形柱");
    const cplx eb = nb * nb, ep = np * np;
    const double fx = (x1 - x0) / Lx, fy = (y1 - y0) / Ly;
    const cplx hx = 1.0 / ((1.0 - fx) / eb + fx / ep);   // 中间行沿 x 的调和平均（Cx 的 x 逆规则）
    const cplx hy = 1.0 / ((1.0 - fy) / eb + fy / ep);   // 中间列沿 y 的调和平均（Cy 的 y 逆规则）
    const cplx eps = (1.0 - fy) * eb + fy * ((1.0 - fx) * eb + fx * ep);   // 面积平均
    const cplx cx = (1.0 - fy) * eb + fy * hx;                          // 先沿 x 取调和平均，再沿 y 取算术平均
    const cplx cy = (1.0 - fx) * eb + fx * hy;                          // 先沿 y 取调和平均，再沿 x 取算术平均
    const d2::LayerOperators2D op = d2::layer_operators(L, Lx, Ly, 0, 0, Factorization2D::Li);
    CHECK(op.eps.rows() == 1 && op.cx.rows() == 1 && op.cy.rows() == 1);
    const double de = std::abs(op.eps(0, 0) - eps) / std::abs(eps), dx = std::abs(op.cx(0, 0) - cx) / std::abs(cx),
                 dy = std::abs(op.cy(0, 0) - cy) / std::abs(cy);
    say("  相对误差：Eps %.2e、Cx %.2e、Cy %.2e（Cx 与 Cy 相差 %.3f，说明两种规则确实不同）\n", de, dx, dy, std::abs(cx - cy) / std::abs(cx));
    CHECK_LE(de, 1e-14);
    CHECK_LE(dx, 1e-14);
    CHECK_LE(dy, 1e-14);
    CHECK(std::abs(cx - cy) / std::abs(cx) > 1e-3);
    // Laurent：三者都是面积平均
    const d2::LayerOperators2D lo = d2::layer_operators(L, Lx, Ly, 0, 0, Factorization2D::Laurent);
    CHECK(lo.cx(0, 0) == lo.eps(0, 0) && lo.cy(0, 0) == lo.eps(0, 0));
    CHECK_LE(std::abs(lo.eps(0, 0) - eps) / std::abs(eps), 1e-14);
    // 起点不是 0 的写法（x 剖面平移 0.37、y 边界平移 −0.6）给出同样的数
    const Layer2D S = Layer2D::patterned(0.3, {-0.6, -0.6 + y0, -0.6 + y1, -0.6 + Ly},
                                         {uniform_profile(Lx, nb), XProfile2D{{0.37, 0.37 + x0, 0.37 + x1, 0.37 + Lx}, {nb, np, nb}}, uniform_profile(Lx, nb)}, "平移柱");
    const d2::LayerOperators2D os = d2::layer_operators(S, Lx, Ly, 0, 0, Factorization2D::Li);
    // 与原结构只差一个 x、y 方向的平移（周期结构），M = 0 的三个值相同
    CHECK_LE(std::abs(os.eps(0, 0) - eps) / std::abs(eps), 1e-14);
    CHECK_LE(std::abs(os.cx(0, 0) - cx) / std::abs(cx), 1e-14);
    CHECK_LE(std::abs(os.cy(0, 0) - cy) / std::abs(cy), 1e-14);
}

// ---------------------------------------------------------------------------------------------
// 8. 结构性质

// 一维 TE、TM 层矩阵（rcwa1d.hpp 的 layer_matrix）所需的 kx：kx_m = nI sin θ − m λ/Λ，m = −M…M。
static Vector kx_1d(double nI, double theta_deg, double wavelength, double period, int M) {
    const double s = nI * std::sin(theta_deg * kPi / 180.0);
    Vector kx(static_cast<std::size_t>(2 * M + 1));
    for (int j = 0; j <= 2 * M; ++j) kx[static_cast<std::size_t>(j)] = s - (j - M) * wavelength / period;
    return kx;
}
// TM：A = C·(Kx·Eps⁻¹·Kx − I)，其中 C 是逆规则算子 ⟦1/ε⟧⁻¹。
static Matrix tm_layer_matrix(const Matrix& eps, const Matrix& c, const Vector& kx) {
    Matrix B = scale_rows(solve(eps, Matrix::diagonal(kx)), kx);
    for (int i = 0; i < B.rows(); ++i) B(i, i) -= 1.0;
    return c * B;
}
// TE：A = Kx² − Eps。
static Matrix te_layer_matrix(const Matrix& eps, const Vector& kx) {
    Matrix A = -eps;
    for (int i = 0; i < A.rows(); ++i) A(i, i) += kx[static_cast<std::size_t>(i)] * kx[static_cast<std::size_t>(i)];
    return A;
}

static void test_structure() {
    say("[结构性质：块 Toeplitz、Laurent、y 不变 / x 不变、一维极限]\n");
    const std::vector<OpsCase> cases = build_cases();

    // (a) Eps 的块 Toeplitz 结构：(m,n),(m′,n′) 元只依赖 (m−m′, n−n′)
    double worst_t = 0.0;
    for (const OpsCase& c : cases) {
        const d2::LayerOperators2D op = ops_of(c, c.M1, c.M2);
        const double d = toeplitz_defect(op.eps, c.M1, c.M2);
        worst_t = (std::max)(worst_t, d);
        CHECK_LE(d, 1e-14);
    }
    {   // 更大的截断 + 不对称的 M
        const OpsCase& c = find_case(cases, "n81_sampled");
        const d2::LayerOperators2D op = ops_of(c, 7, 4);
        const double d = toeplitz_defect(op.eps, 7, 4);
        worst_t = (std::max)(worst_t, d);
        CHECK_LE(d, 1e-14);
    }
    say("  Eps 的块 Toeplitz 偏差（%zu 个算例 + M = (7, 4)）最大 %.2e\n", cases.size(), worst_t);

    // (b) Laurent：Cx = Cy = Eps，逐位相同
    for (const OpsCase& c : cases) {
        const d2::LayerOperators2D lo = d2::layer_operators(c.layer, c.Lx, c.Ly, c.M1, c.M2, Factorization2D::Laurent);
        CHECK(same_bits(lo.cx, lo.eps) && same_bits(lo.cy, lo.eps));
        // Eps 与因式分解方式无关
        CHECK(same_bits(lo.eps, d2::layer_operators(c.layer, c.Lx, c.Ly, c.M1, c.M2, Factorization2D::Li).eps));
    }

    // (c) y 不变的层（一个 y 分段）：Eps、Cx 对 n 块对角，每个对角块就是 M2 = 0 时的一维算子；Cy ≈ Eps
    {
        const double Lx = 0.574, Ly = 0.8;
        const Layer2D L = Layer2D::patterned(0.3, {0.0, Ly}, {XProfile2D{{0.0, 0.172, 0.35, Lx}, {cplx{1.46, 0.0}, 1.0, cplx{1.8, 0.13}}}}, "y 不变");
        const int M1 = 6, M2 = 2;
        const d2::LayerOperators2D op = d2::layer_operators(L, Lx, Ly, M1, M2, Factorization2D::Li);
        const d2::LayerOperators2D one = d2::layer_operators(L, Lx, Ly, M1, 0, Factorization2D::Li);   // 一维算子
        const double off_e = off_diagonal_in_n(op.eps, M2), off_c = off_diagonal_in_n(op.cx, M2);
        double dblk_e = 0.0, dblk_c = 0.0;
        for (int n = -M2; n <= M2; ++n) {
            dblk_e = (std::max)(dblk_e, rel_diff(block_of_n(op.eps, M1, M2, n), one.eps));
            dblk_c = (std::max)(dblk_c, rel_diff(block_of_n(op.cx, M1, M2, n), one.cx));
        }
        const double d_cy = rel_diff(op.cy, op.eps);
        say("  y 不变：Eps、Cx 的 n≠n′ 元 %.1e、%.1e；对角块与一维算子的差 %.1e、%.1e；Cy 与 Eps 的差 %.1e\n", off_e, off_c, dblk_e, dblk_c, d_cy);
        CHECK_LE(off_e, 1e-14);
        CHECK_LE(off_c, 1e-14);
        CHECK_LE(dblk_e, 1e-14);
        CHECK_LE(dblk_c, 1e-14);
        CHECK_LE(d_cy, 1e-13);
        CHECK(one.eps.rows() == 2 * M1 + 1);
    }

    // (d) x 不变的层（每个 y 分段内只有一个 x 分段）：Eps、Cy 对 m 块对角，对角块是 M1 = 0 时的一维算子；Cx ≈ Eps
    {
        const double Lx = 0.9, Ly = 1.2;
        const Layer2D L = Layer2D::patterned(0.3, {0.1, 0.4, 0.55, 1.3},
                                             {uniform_profile(Lx, 1.0), uniform_profile(Lx, cplx{2.2, 0.05}), uniform_profile(Lx, 1.5)}, "x 不变");
        const int M1 = 2, M2 = 5;
        const d2::LayerOperators2D op = d2::layer_operators(L, Lx, Ly, M1, M2, Factorization2D::Li);
        const d2::LayerOperators2D one = d2::layer_operators(L, Lx, Ly, 0, M2, Factorization2D::Li);
        const double off_e = off_diagonal_in_m(op.eps, M2), off_c = off_diagonal_in_m(op.cy, M2);
        double dblk_e = 0.0, dblk_c = 0.0;
        for (int m = -M1; m <= M1; ++m) {
            dblk_e = (std::max)(dblk_e, rel_diff(block_of_m(op.eps, M1, M2, m), one.eps));
            dblk_c = (std::max)(dblk_c, rel_diff(block_of_m(op.cy, M1, M2, m), one.cy));
        }
        const double d_cx = rel_diff(op.cx, op.eps);
        say("  x 不变：Eps、Cy 的 m≠m′ 元 %.1e、%.1e；对角块与一维算子的差 %.1e、%.1e；Cx 与 Eps 的差 %.1e\n", off_e, off_c, dblk_e, dblk_c, d_cx);
        CHECK_LE(off_e, 1e-14);
        CHECK_LE(off_c, 1e-14);
        CHECK_LE(dblk_e, 1e-14);
        CHECK_LE(dblk_c, 1e-14);
        CHECK_LE(d_cx, 1e-13);
    }

    // (e) 一维极限：与 rcwa1d.hpp 的 layer_matrix（TE：Kx² − ⟦ε⟧；TM：⟦1/ε⟧⁻¹(Kx ⟦ε⟧⁻¹ Kx − I)）比较。
    //     沿 x 的光栅（M2 = 0、一个 y 分段）与沿 y 的光栅（M1 = 0、每个 y 分段内一个 x 分段）各一例。
    {
        const double nI = 1.0, theta = 21.0, wl = 0.83;
        const std::vector<double> edges{0.0, 0.172, 0.31, 0.574};
        const std::vector<cplx> nv{cplx{1.46, 0.0}, cplx{1.0, 0.0}, cplx{1.8, 0.13}};
        const rcwa::Layer layer1d = rcwa::Layer::grating(0.3, edges, nv);
        const double period = 0.574;
        for (int M : {0, 3, 10}) {
            const Vector kx = kx_1d(nI, theta, wl, period, M);
            const Matrix te1 = rcwa::layer_matrix(layer1d, period, wl, nI, theta, M, rcwa::Polarization::TE);
            const Matrix tm1 = rcwa::layer_matrix(layer1d, period, wl, nI, theta, M, rcwa::Polarization::TM);
            // 沿 x 的光栅
            {
                const Layer2D L = Layer2D::patterned(0.3, {0.0, 0.8}, {XProfile2D{edges, nv}}, "沿 x 的光栅");
                const d2::LayerOperators2D op = d2::layer_operators(L, period, 0.8, M, 0, Factorization2D::Li);
                const double d_te = rel_diff(te_layer_matrix(op.eps, kx), te1), d_tm = rel_diff(tm_layer_matrix(op.eps, op.cx, kx), tm1);
                say("  一维极限（沿 x，M = %2d）：TE 层矩阵相对差 %.1e，TM 层矩阵相对差 %.1e\n", M, d_te, d_tm);
                CHECK_LE(d_te, 1e-12);
                CHECK_LE(d_tm, 1e-11);
            }
            // 沿 y 的光栅：y 分段 = edges，每段内 x 剖面只有一个取值
            {
                std::vector<XProfile2D> rows;
                for (const cplx& n : nv) rows.push_back(uniform_profile(0.8, n));
                const Layer2D L = Layer2D::patterned(0.3, edges, rows, "沿 y 的光栅");
                const d2::LayerOperators2D op = d2::layer_operators(L, 0.8, period, 0, M, Factorization2D::Li);
                const double d_te = rel_diff(te_layer_matrix(op.eps, kx), te1), d_tm = rel_diff(tm_layer_matrix(op.eps, op.cy, kx), tm1);
                say("  一维极限（沿 y，M = %2d）：TE 层矩阵相对差 %.1e，TM 层矩阵相对差 %.1e\n", M, d_te, d_tm);
                CHECK_LE(d_te, 1e-12);
                CHECK_LE(d_tm, 1e-11);
            }
        }
    }
}

// ---------------------------------------------------------------------------------------------
// 9. x ↔ y 互换

static void test_transpose() {
    say("[x↔y 互换：转置结构的 Cx、Cy 互换，Eps 不变]\n");
    const std::vector<OpsCase> cases = build_cases();
    // 十字形（x、y 互换对称）：中间一行全填满，上下两行只有中间一条竖条
    const double L1 = 1.0;
    const cplx nb{1.0, 0.0}, nc{2.2, 0.3};
    Layer2D cross = Layer2D::patterned(0.2, {0.0, 0.35, 0.65, 1.0},
                                       {XProfile2D{{0.0, 0.35, 0.65, 1.0}, {nb, nc, nb}}, uniform_profile(L1, nc), XProfile2D{{0.0, 0.35, 0.65, 1.0}, {nb, nc, nb}}}, "十字");
    // 矩形柱（Lx ≠ Ly，复折射率）
    Layer2D rect = Layer2D::patterned(0.2, {0.0, 0.4, 1.0, 1.3},
                                      {uniform_profile(0.9, 1.45), XProfile2D{{0.0, 0.25, 0.7, 0.9}, {1.45, cplx{1.8, 0.13}, 1.45}}, uniform_profile(0.9, 1.45)}, "矩形柱");
    struct Item {
        const char* name;
        const Layer2D* layer;
        double Lx, Ly;
        int M1, M2;
    };
    std::vector<Item> items{{"十字 M=(3,3)", &cross, L1, L1, 3, 3},
                            {"矩形柱 M=(2,4)", &rect, 0.9, 1.3, 2, 4},
                            {"矩形柱 M=(4,2)", &rect, 0.9, 1.3, 4, 2}};
    for (const OpsCase& c : cases) items.push_back({c.name, &c.layer, c.Lx, c.Ly, c.M1, c.M2});
    double worst = 0.0;
    for (const Item& it : items) {
        const Layer2D T = transpose_layer(*it.layer, it.Lx);
        const d2::LayerOperators2D a = d2::layer_operators(*it.layer, it.Lx, it.Ly, it.M1, it.M2, Factorization2D::Li);
        const d2::LayerOperators2D b = d2::layer_operators(T, it.Ly, it.Lx, it.M2, it.M1, Factorization2D::Li);
        const double de = transposed_diff(a.eps, b.eps, it.M1, it.M2);
        const double dx = transposed_diff(a.cx, b.cy, it.M1, it.M2);   // 原结构的 Cx（x 法向）对应转置结构的 Cy
        const double dy = transposed_diff(a.cy, b.cx, it.M1, it.M2);
        say("  %-18s Eps %.2e  Cx↔Cy′ %.2e  Cy↔Cx′ %.2e\n", it.name, de, dx, dy);
        CHECK_LE(de, 1e-13);
        CHECK_LE(dx, 1e-13);
        CHECK_LE(dy, 1e-13);
        worst = (std::max)(worst, (std::max)(de, (std::max)(dx, dy)));
    }
    // 十字形在 x↔y 互换下不变：Cy = P·Cx·Pᵀ（转置结构就是它自己）
    {
        const d2::LayerOperators2D a = d2::layer_operators(cross, L1, L1, 3, 3, Factorization2D::Li);
        const double dx = transposed_diff(a.cx, a.cy, 3, 3), de = transposed_diff(a.eps, a.eps, 3, 3);
        say("  十字形自身：P·Cx·Pᵀ 与 Cy 相差 %.2e，P·Eps·Pᵀ 与 Eps 相差 %.2e\n", dx, de);
        CHECK_LE(dx, 1e-13);
        CHECK_LE(de, 1e-13);
        // 且 Cx ≠ Cy（互换后才相等）：规则确实在区分两个方向
        CHECK(rel_diff(a.cx, a.cy) > 1e-3);
    }
    say("  最大相对差 %.2e\n", worst);
}

// ---------------------------------------------------------------------------------------------
// 10. 线程

static void test_threads() {
    say("[parallel = true 与串行逐位相同（4 个线程）]\n");
    const std::vector<OpsCase> cases = build_cases();
    set_num_threads(4);
    int same = 0;
    for (const OpsCase& c : cases) {
        const bool ok = same_bits(ops_of(c, c.M1, c.M2, true), ops_of(c, c.M1, c.M2, false));
        same += ok;
        CHECK(ok);
    }
    const OpsCase& big = find_case(cases, "n81_sampled");
    const bool ok_big = same_bits(ops_of(big, 12, 12, true), ops_of(big, 12, 12, false));
    CHECK(ok_big);
    // 算子在多个线程里同时被调用（solve2d 在层之间并行时的情形）
    std::vector<d2::LayerOperators2D> out(6);
    parallel_for(0, 6, [&](int i) { out[static_cast<std::size_t>(i)] = ops_of(big, 4 + i % 3, 4, true); });
    bool ok_nested = true;
    for (int i = 0; i < 6; ++i) ok_nested = ok_nested && same_bits(out[static_cast<std::size_t>(i)], ops_of(big, 4 + i % 3, 4, false));
    CHECK(ok_nested);
    set_num_threads(1);
    say("  %d / %zu 个算例相同；N = 625 相同：%s；层间并行里再用 parallel = true：%s\n", same, cases.size(), ok_big ? "是" : "否", ok_nested ? "是" : "否");
}

// ---------------------------------------------------------------------------------------------
// 11. 输入校验与失败

template <class F>
static bool invalid_with(F&& f, const char* must_contain) {
    try {
        f();
    } catch (const std::invalid_argument& e) {
        return must_contain == nullptr || std::string(e.what()).find(must_contain) != std::string::npos;
    } catch (...) {
    }
    return false;
}

static Layer2D good_layer(const char* name = "校验层") {
    return Layer2D::patterned(0.3, {0.0, 0.5, 1.0}, {XProfile2D{{0.0, 0.4, 1.0}, {1.0, 2.0}}, XProfile2D{{0.0, 0.6, 1.0}, {1.5, 1.0}}}, name);
}

static void test_errors() {
    say("[输入校验与失败]\n");
    auto run = [](const Layer2D& L, double Lx = 1.0, double Ly = 1.0, int M1 = 1, int M2 = 1) {
        return d2::layer_operators(L, Lx, Ly, M1, M2, Factorization2D::Li);
    };
    CHECK((void(run(good_layer())), true));

    // 错误信息里要带层名
    {
        Layer2D L = good_layer();
        L.y_edges = {0.0, 0.5, 0.4};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.y_edges = {0.0, 0.5, 0.5, 1.0};     // 相等的边界也不是严格递增
        L.x_profiles.push_back(L.x_profiles.back());
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[1].edges = {0.0, 0.7, 0.6, 1.0};
        L.x_profiles[1].n_values = {1.0, 2.0, 3.0};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.y_edges = {0.0, 0.5, 0.9};          // 不恰好覆盖一个 y 周期
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[0].edges = {0.0, 0.4, 1.1};   // 不恰好覆盖一个 x 周期
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[0].n_values = {1.0};     // n_values 个数不对
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L.x_profiles[0].n_values = {1.0, 2.0, 3.0};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles.pop_back();              // x_profiles 与 y 分段数不一致
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles.push_back(L.x_profiles[0]);
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.y_edges = {0.0};                    // 没有分段
        L.x_profiles.clear();
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[0].edges = {0.0, std::numeric_limits<double>::quiet_NaN(), 1.0};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.y_edges[1] = std::numeric_limits<double>::infinity();
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[1].n_values[1] = cplx{std::numeric_limits<double>::quiet_NaN(), 0.0};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L.x_profiles[1].n_values[1] = cplx{1.0, std::numeric_limits<double>::infinity()};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[0].n_values[0] = 0.0;    // n = 0：1/ε 无定义
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        // 均匀层的折射率非有限
        CHECK(invalid_with([&] { run(Layer2D::uniform(0.1, cplx{std::numeric_limits<double>::quiet_NaN(), 0.0}, "均匀校验")); }, "均匀校验"));
        CHECK(invalid_with([&] { run(Layer2D::uniform(0.1, cplx{1.0, std::numeric_limits<double>::infinity()}, "均匀校验")); }, "均匀校验"));
        // 没有层名时也能给出信息
        CHECK(invalid_with([&] { run(Layer2D::uniform(0.1, cplx{std::numeric_limits<double>::quiet_NaN(), 0.0})); }, "未命名"));
    }
    // 周期的相对容差 1e-9：差 1e-10 通过，差 1e-8 不通过
    {
        Layer2D L = good_layer();
        L.y_edges = {0.0, 0.5, 1.0 + 1e-10};
        CHECK((void(run(L)), true));
        L.y_edges = {0.0, 0.5, 1.0 + 1e-8};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();
        L.x_profiles[1].edges = {0.0, 0.6, 1.0 - 1e-10};
        CHECK((void(run(L)), true));
        L.x_profiles[1].edges = {0.0, 0.6, 1.0 - 1e-8};
        CHECK(invalid_with([&] { run(L); }, "校验层"));
        L = good_layer();       // 周期 100 的结构：容差是相对的，绝对差 5e-8 仍然通过
        L.y_edges = {0.0, 50.0, 100.0 + 5e-8};
        L.x_profiles = {XProfile2D{{0.0, 40.0, 100.0}, {1.0, 2.0}}, XProfile2D{{0.0, 60.0, 100.0}, {1.5, 1.0}}};
        CHECK((void(run(L, 100.0, 100.0)), true));
    }
    // M 为负、周期非法（均匀层也一样）
    CHECK(invalid_with([&] { run(good_layer(), 1.0, 1.0, -1, 1); }, nullptr));
    CHECK(invalid_with([&] { run(good_layer(), 1.0, 1.0, 1, -2); }, nullptr));
    CHECK(invalid_with([&] { run(Layer2D::uniform(0.1, 1.5), 1.0, 1.0, -1, 0); }, nullptr));
    CHECK(invalid_with([&] { run(good_layer(), 0.0, 1.0); }, nullptr));
    CHECK(invalid_with([&] { run(good_layer(), 1.0, -1.0); }, nullptr));
    CHECK(invalid_with([&] { run(good_layer(), std::numeric_limits<double>::quiet_NaN(), 1.0); }, nullptr));
    CHECK(invalid_with([&] { run(good_layer(), 1.0, std::numeric_limits<double>::infinity()); }, nullptr));
    CHECK(invalid_with([&] { run(good_layer(), 1.0, 1.0, 50000, 50000); }, nullptr));   // N 超出 int 范围
    // 错误的结构层在 Laurent 模式下同样校验
    {
        Layer2D L = good_layer();
        L.y_edges = {0.0, 0.5, 0.4};
        CHECK(invalid_with([&] { d2::layer_operators(L, 1.0, 1.0, 1, 1, Factorization2D::Laurent); }, "校验层"));
    }
    // 逆规则的 Toeplitz 阵奇异：M1 = 0，一个 y 分段，x 剖面两半各占一半、ε = +1 与 −1（n = 1 与 n = i）：⟦1/ε⟧ = 0.5 − 0.5 = 0
    {
        const Layer2D L = Layer2D::patterned(0.3, {0.0, 1.0}, {XProfile2D{{0.0, 0.5, 1.0}, {1.0, cplx{0.0, 1.0}}}}, "奇异层");
        bool singular = false;
        try {
            d2::layer_operators(L, 1.0, 1.0, 0, 0, Factorization2D::Li);
        } catch (const std::runtime_error& e) {
            singular = std::string(e.what()).find("奇异层") != std::string::npos;
        }
        CHECK(singular);
        // 沿 y 的逆规则同理
        const Layer2D Ly = Layer2D::patterned(0.3, {0.0, 0.5, 1.0}, {uniform_profile(1.0, 1.0), uniform_profile(1.0, cplx{0.0, 1.0})}, "奇异层");
        bool singular_y = false;
        try {
            d2::layer_operators(Ly, 1.0, 1.0, 0, 0, Factorization2D::Li);
        } catch (const std::runtime_error& e) {
            singular_y = std::string(e.what()).find("奇异层") != std::string::npos;
        }
        CHECK(singular_y);
        // 并行时异常照常传出：两个 y 分段都奇异（parallel_for 真的分给两个线程），以及 x 切点分段里的奇异
        const Layer2D two = Layer2D::patterned(0.3, {0.0, 0.5, 1.0}, {XProfile2D{{0.0, 0.5, 1.0}, {1.0, cplx{0.0, 1.0}}}, XProfile2D{{0.0, 0.5, 1.0}, {1.0, cplx{0.0, 1.0}}}}, "奇异层");
        set_num_threads(4);
        bool thrown = false, message_ok = false;
        try {
            d2::layer_operators(two, 1.0, 1.0, 0, 0, Factorization2D::Li, true);
        } catch (const std::runtime_error& e) {
            thrown = true;
            message_ok = std::string(e.what()).find("奇异层") != std::string::npos;
        }
        CHECK(thrown && message_ok);
        CHECK_THROWS(d2::layer_operators(Ly, 1.0, 1.0, 0, 0, Factorization2D::Li, true), std::runtime_error);
        set_num_threads(1);
    }
    // ε = n² 溢出、下溢为零、或 1/ε 溢出：一律是参数非法（Python 里是 inf/NaN）
    {
        const double huge = 1e160, tiny = 1e-160, zero_sq = 1e-200;
        CHECK(invalid_with([&] { run(Layer2D::patterned(0.3, {0.0, 1.0}, {XProfile2D{{0.0, 0.5, 1.0}, {huge, 1.0}}}, "溢出层")); }, "溢出层"));
        CHECK(invalid_with([&] { run(Layer2D::patterned(0.3, {0.0, 1.0}, {XProfile2D{{0.0, 0.5, 1.0}, {tiny, 1.0}}}, "溢出层")); }, "溢出层"));
        CHECK(invalid_with([&] { run(Layer2D::patterned(0.3, {0.0, 1.0}, {XProfile2D{{0.0, 0.5, 1.0}, {zero_sq, 1.0}}}, "溢出层")); }, "溢出层"));
        CHECK(invalid_with([&] { run(Layer2D::uniform(0.1, huge, "均匀溢出")); }, "均匀溢出"));
        // 均匀层允许 n = 0（ε = 0 的矩阵就是零，求解层自己处理）
        const d2::LayerOperators2D z = run(Layer2D::uniform(0.1, 0.0), 1.0, 1.0, 1, 1);
        CHECK(max_abs(z.eps) == 0.0 && max_abs(z.cx) == 0.0 && max_abs(z.cy) == 0.0);
    }
}

// ---------------------------------------------------------------------------------------------
// 12. 性能与 N = 625 的结构性质

static double best_time_ms(const std::function<void()>& f, int repeats) {
    double best = 1e300;
    for (int r = 0; r < repeats; ++r) {
        const auto t0 = std::chrono::steady_clock::now();
        f();
        const auto t1 = std::chrono::steady_clock::now();
        best = (std::min)(best, std::chrono::duration<double, std::milli>(t1 - t0).count());
    }
    return best;
}

static void test_performance_and_large() {
    say("[性能与 N = 625 的结构性质]\n");
    const std::vector<OpsCase> cases = build_cases();
    const OpsCase& c = find_case(cases, "n81_sampled");   // 5 个 y 分段、x 切点互不相同、复折射率
    const int threads = (std::min)(4, hardware_threads());
    for (int M : {4, 8, 12}) {
        const int N = (2 * M + 1) * (2 * M + 1);
        d2::LayerOperators2D serial, par;
        const double t1 = best_time_ms([&] { serial = ops_of(c, M, M, false); }, 3);
        set_num_threads(threads);
        const double tp = best_time_ms([&] { par = ops_of(c, M, M, true); }, 3);
        set_num_threads(1);
        say("  N = %3d（M = %2d）：layer_operators 单线程 %.2f ms；parallel = true（%d 线程）%.2f ms；输出 3×%.2f MB\n", N, M, t1, threads, tp,
            16.0 * N * N / 1048576.0);
        CHECK(same_bits(serial, par));
        CHECK(serial.eps.rows() == N && serial.cx.rows() == N && serial.cy.rows() == N);
        CHECK(serial.eps.all_finite() && serial.cx.all_finite() && serial.cy.all_finite());
        CHECK_LE(t1, 20000.0);   // 很宽的上限：只为发现数量级上的退化（实测约 1 ms 到数十 ms）
    }
    // N = 625 的结构性质（不依赖 Python）
    const int M = 12, N = 625;
    const d2::LayerOperators2D op = ops_of(c, M, M);
    const double td = toeplitz_defect(op.eps, M, M);
    say("  N = 625：Eps 的块 Toeplitz 偏差 %.2e\n", td);
    CHECK_LE(td, 1e-14);
    const Layer2D T = transpose_layer(c.layer, c.Lx);
    const d2::LayerOperators2D ot = d2::layer_operators(T, c.Ly, c.Lx, M, M, Factorization2D::Li);
    const double de = transposed_diff(op.eps, ot.eps, M, M), dx = transposed_diff(op.cx, ot.cy, M, M), dy = transposed_diff(op.cy, ot.cx, M, M);
    say("  N = 625：转置结构 Eps %.2e、Cx↔Cy′ %.2e、Cy↔Cx′ %.2e\n", de, dx, dy);
    CHECK_LE(de, 1e-12);
    CHECK_LE(dx, 1e-12);
    CHECK_LE(dy, 1e-12);
    const d2::LayerOperators2D lo = d2::layer_operators(c.layer, c.Lx, c.Ly, M, M, Factorization2D::Laurent);
    CHECK(same_bits(lo.eps, op.eps) && same_bits(lo.cx, lo.eps) && same_bits(lo.cy, lo.eps));
    // 同一结构在 N = 625 与 N = 81 的 Eps：低阶谐波的 ⟦ε⟧ 元素相同（取决于谐波差，与截断无关）
    const d2::LayerOperators2D op81 = ops_of(c, 4, 4);
    double worst = 0.0;
    for (int m = -2; m <= 2; ++m)
        for (int n = -2; n <= 2; ++n)
            for (int mp = -2; mp <= 2; ++mp)
                for (int np = -2; np <= 2; ++np)
                    worst = (std::max)(worst, std::abs(op.eps(rcwa::harmonic_index_2d(m, n, M, M), rcwa::harmonic_index_2d(mp, np, M, M)) -
                                                       op81.eps(rcwa::harmonic_index_2d(m, n, 4, 4), rcwa::harmonic_index_2d(mp, np, 4, 4))));
    CHECK_LE(worst, 1e-14);
    (void)N;
}

int main() {
    test_fourier_toeplitz_seg();
    test_eps_at();
    test_merge_x_cuts();
    test_assemble();
    test_uniform();
    test_reference_cases();
    test_closed_form();
    test_structure();
    test_transpose();
    test_threads();
    test_errors();
    test_performance_and_large();
    say("通过 %d / 共 %d\n", g_pass, g_total);
    return g_pass == g_total ? 0 : 1;
}
